import ipaddress
import logging

from taf.fdsw.rc.schemas.exceptions import raise_value_error

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Validator:
    @staticmethod
    def validate_ip_address(address):
        """
        Checks if it is a valid IPv4 or IPv6 address Otherwise, raises value error.

        :param address: Ipv4 or IPv6 address
        """
        if address:
            ipaddress.ip_address(address.encode().decode())
            logger.debug("given address {}".format(address))
            return True
        else:
            return False

    @staticmethod
    def validate_param(name, value, validity_check):
        if validity_check and value:
            return str(value)
        elif validity_check:
            return value
        else:
            raise_value_error(param=name, value=str(value))


class AutoconnectionParametersBuilder19A:
    def __init__(self, **kwargs):
        self.management_plane_parameters = self._get_management_plane_parameters(**kwargs)
        self.certifcate_parameters = self._get_certifcate_parameters(**kwargs)

    def as_dict(self):
        attributes = {}
        if self.management_plane_parameters:
            attributes.update(managementPlaneParameters=self.management_plane_parameters)
        if self.certifcate_parameters:
            attributes.update(certificateServerParameters=self.certifcate_parameters)
        return attributes

    def _get_management_plane_parameters(self, **kwargs):  # noqa: C901
        management_plane_parameters = {}

        if "primary_ip_address" in kwargs:
            primary_ip_address = kwargs["primary_ip_address"]
            management_plane_parameters.update(
                ipAddress=Validator.validate_param(
                    "primary_ip_address", primary_ip_address, (primary_ip_address is None or Validator.validate_ip_address(primary_ip_address))
                )
            )

        if "primary_prefix_length" in kwargs:
            primary_prefix_length = kwargs["primary_prefix_length"]
            management_plane_parameters.update(
                prefixLength=Validator.validate_param(
                    "primary_prefix_length", primary_prefix_length, (primary_prefix_length is None or (0 <= primary_prefix_length <= 127))
                )
            )

        if "primary_gateway" in kwargs:
            primary_gateway = kwargs["primary_gateway"]
            management_plane_parameters.update(
                gateway=Validator.validate_param(
                    "primary_gateway", primary_gateway, (primary_gateway is None or Validator.validate_ip_address(primary_gateway))
                )
            )

        if "identification_entity_ip_address" in kwargs:
            identification_entity_ip_address = kwargs["identification_entity_ip_address"]
            management_plane_parameters.update(
                omsIpAddress=Validator.validate_param(
                    "identification_entity_ip_address",
                    identification_entity_ip_address,
                    (identification_entity_ip_address is None or Validator.validate_ip_address(identification_entity_ip_address)),
                )
            )

        if "vlan_id" in kwargs:
            vlan_id = kwargs["vlan_id"]
            management_plane_parameters.update(vlanId=Validator.validate_param("vlan_id", vlan_id, (vlan_id is None or (0 <= vlan_id <= 4095))))

        if "secondary_ip_address" in kwargs:
            secondary_ip_address = kwargs["secondary_ip_address"]
            management_plane_parameters.update(
                secIpAddress=Validator.validate_param(
                    "secondary_ip_address",
                    secondary_ip_address,
                    (secondary_ip_address is None or Validator.validate_ip_address(secondary_ip_address)),
                )
            )

        if "secondary_prefix_length" in kwargs:
            secondary_prefix_length = kwargs["secondary_prefix_length"]
            management_plane_parameters.update(
                secPrefixLength=Validator.validate_param(
                    "secondary_prefix_length", secondary_prefix_length, (secondary_prefix_length is None or (0 <= secondary_prefix_length <= 127))
                )
            )

        if "secondary_vlan_id" in kwargs:
            secondary_vlan_id = kwargs["secondary_vlan_id"]
            management_plane_parameters.update(
                secVlanId=Validator.validate_param(
                    "secondary_vlan_id", secondary_vlan_id, (secondary_vlan_id is None or (0 <= secondary_vlan_id <= 4095))
                )
            )


        return management_plane_parameters

    def _get_certifcate_parameters(self, **kwargs):
        certifcate_parameters = {}

        if "ip_address" in kwargs:
            ip_address = kwargs["ip_address"]

            certifcate_parameters.update(
                ipAddress=Validator.validate_param("ip_address", ip_address, (ip_address is None or Validator.validate_ip_address(ip_address)))
            )

        if "server_port" in kwargs:
            server_port = kwargs["server_port"]

            certifcate_parameters.update(
                serverPort=Validator.validate_param("server_port", server_port, (server_port is None or (0 <= server_port <= 65535)))
            )

        if "subject_name" in kwargs:
            certifcate_parameters.update(subjectName=kwargs["subject_name"])

        if "directory" in kwargs:
            certifcate_parameters.update(directory=kwargs["directory"])

        if "vpn_gateway_ip_address" in kwargs:
            vpn_gateway_ip_address = kwargs["vpn_gateway_ip_address"]

            certifcate_parameters.update(
                vpnGatewayIpAddress=Validator.validate_param(
                    "vpn_gateway_ip_address",
                    vpn_gateway_ip_address,
                    (vpn_gateway_ip_address is None or Validator.validate_ip_address(vpn_gateway_ip_address)),
                )
            )

        return certifcate_parameters
